#include <chrono>
#include <memory>

#include <rclcpp/rclcpp.hpp>

using namespace std::chrono_literals;

class ClockDemo : public rclcpp::Node {
 public:
  explicit ClockDemo(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("clock_demo", options) {
    node_timer_ = create_timer(1s, [this] { report("node timer"); });       // the node's clock: ROS time
    wall_timer_ = create_wall_timer(1s, [this] { report("wall timer"); });  // a steady clock, always
  }

 private:
  void report(const char* source) const {
    RCLCPP_INFO(get_logger(), "%s: ROS %.3f s, system %.3f s, steady %.3f s", source, now().seconds(),
                system_clock_.now().seconds(), steady_clock_.now().seconds());
  }

  rclcpp::Clock system_clock_{RCL_SYSTEM_TIME};
  rclcpp::Clock steady_clock_{RCL_STEADY_TIME};
  rclcpp::TimerBase::SharedPtr node_timer_;
  rclcpp::TimerBase::SharedPtr wall_timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<ClockDemo>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <string>

using namespace std::chrono_literals;

// A time on the node's clock, as rclcpp::Time::nanoseconds() returns it.
struct Stamp {
  std::int64_t ns;
};

[[nodiscard]] constexpr Stamp at(std::chrono::nanoseconds since_zero) { return Stamp{since_zero.count()}; }

// Says whether an input is fresh. It never reads a clock: every caller says what time it is.
class Freshness {
 public:
  explicit Freshness(std::chrono::nanoseconds timeout) : timeout_{timeout} {}

  void on_message(Stamp now) { last_ = now; }

  // How long ago the last message arrived, or nothing if none has.
  [[nodiscard]] std::optional<std::chrono::nanoseconds> silence(Stamp now) const {
    if (!last_) return std::nullopt;
    return std::chrono::nanoseconds{now.ns - last_->ns};
  }

  [[nodiscard]] bool is_stale(Stamp now) const {
    const std::optional<std::chrono::nanoseconds> s = silence(now);
    return !s || *s > timeout_;
  }

 private:
  std::chrono::nanoseconds timeout_;
  std::optional<Stamp> last_;
};

void report(const Freshness& odom, Stamp now) {
  const std::optional<std::chrono::nanoseconds> s = odom.silence(now);
  const std::string last = s ? std::format(", last message {} ago", std::chrono::duration_cast<std::chrono::milliseconds>(*s))
                             : std::string{", nothing received"};
  std::cout << std::format("t = {:>6}: {}{}\n", std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::nanoseconds{now.ns}),
                           odom.is_stale(now) ? "stale" : "fresh", last);
}

int main() {
  Freshness odom{500ms};
  report(odom, at(0ms));
  odom.on_message(at(100ms));
  odom.on_message(at(200ms));
  report(odom, at(450ms));
  report(odom, at(700ms));
  report(odom, at(701ms));
}

#include <chrono>
#include <cstdint>
#include <memory>
#include <optional>

#include <nav_msgs/msg/odometry.hpp>
#include <rclcpp/rclcpp.hpp>

using namespace std::chrono_literals;

// Plain C++ with no ROS types, so a test reaches it without starting ROS.
struct Stamp {
  std::int64_t ns;  // as rclcpp::Time::nanoseconds() returns it
};

class Freshness {
 public:
  explicit Freshness(std::chrono::nanoseconds timeout) : timeout_{timeout} {}

  void on_message(Stamp now) { last_ = now; }

  [[nodiscard]] bool is_stale(Stamp now) const {
    return !last_ || std::chrono::nanoseconds{now.ns - last_->ns} > timeout_;
  }

 private:
  std::chrono::nanoseconds timeout_;
  std::optional<Stamp> last_;
};

class OdomWatch : public rclcpp::Node {
 public:
  explicit OdomWatch(const rclcpp::NodeOptions& options = rclcpp::NodeOptions()) : Node("odom_watch", options) {
    subscription_ = create_subscription<nav_msgs::msg::Odometry>(
        "/model/vehicle_green/odometry", rclcpp::QoS(rclcpp::KeepLast(10)),
        [this](const nav_msgs::msg::Odometry& msg) { on_odometry(msg); });
    check_timer_ = create_timer(100ms, [this] { check(); });
    age_timer_ = create_timer(1s, [this] { report_age(); });
  }

 private:
  [[nodiscard]] Stamp stamp_now() const { return Stamp{now().nanoseconds()}; }

  void on_odometry(const nav_msgs::msg::Odometry& msg) {
    freshness_.on_message(stamp_now());
    latest_stamp_ = rclcpp::Time(msg.header.stamp);
  }

  void check() {
    const bool stale = freshness_.is_stale(stamp_now());
    if (stale && !stale_) RCLCPP_WARN(get_logger(), "no odometry for more than 500 ms");
    if (!stale && stale_) RCLCPP_INFO(get_logger(), "odometry is back");
    stale_ = stale;
  }

  void report_age() const {
    if (!latest_stamp_) return;
    const rclcpp::Duration age = now() - *latest_stamp_;
    RCLCPP_INFO(get_logger(), "latest odometry is %.3f s old", age.seconds());
  }

  Freshness freshness_{500ms};
  bool stale_ = true;  // nothing has arrived yet
  std::optional<rclcpp::Time> latest_stamp_;
  rclcpp::Subscription<nav_msgs::msg::Odometry>::SharedPtr subscription_;
  rclcpp::TimerBase::SharedPtr check_timer_;
  rclcpp::TimerBase::SharedPtr age_timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<OdomWatch>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>

using namespace std::chrono_literals;

struct Stamp {
  std::int64_t ns;
};

[[nodiscard]] constexpr Stamp at(std::chrono::nanoseconds since_zero) { return Stamp{since_zero.count()}; }

class Freshness {
 public:
  explicit Freshness(std::chrono::nanoseconds timeout) : timeout_{timeout} {}

  void on_message(Stamp now) { last_ = now; }

  [[nodiscard]] bool is_stale(Stamp now) const {
    return !last_ || std::chrono::nanoseconds{now.ns - last_->ns} > timeout_;
  }

 private:
  std::chrono::nanoseconds timeout_;
  std::optional<Stamp> last_;
};

// The same check, but a time earlier than one already seen means the clock jumped back,
// and nothing received before the jump counts any more.
class JumpAwareFreshness {
 public:
  explicit JumpAwareFreshness(std::chrono::nanoseconds timeout) : timeout_{timeout}, inner_{timeout} {}

  void on_message(Stamp now) {
    see(now);
    inner_.on_message(now);
  }

  [[nodiscard]] bool is_stale(Stamp now) {
    see(now);
    return inner_.is_stale(now);
  }

 private:
  void see(Stamp now) {
    if (latest_ && now.ns < latest_->ns) inner_ = Freshness{timeout_};
    latest_ = now;
  }

  std::chrono::nanoseconds timeout_;
  Freshness inner_;
  std::optional<Stamp> latest_;
};

int main() {
  Freshness plain{500ms};
  JumpAwareFreshness aware{500ms};
  plain.on_message(at(30'000ms));
  aware.on_message(at(30'000ms));
  // The world is reset: ROS time starts again from 0, and no more odometry arrives.
  for (const Stamp now : {at(30'200ms), at(200ms), at(20'000ms), at(30'501ms)}) {
    std::cout << std::format("t = {:>7}: plain {}, jump-aware {}\n",
                             std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::nanoseconds{now.ns}),
                             plain.is_stale(now) ? "stale" : "fresh", aware.is_stale(now) ? "stale" : "fresh");
  }
}
